{
  "name": "llm_adv_pdu_update",
  "confidence": "medium",
  "docstring": "Processes a BLE advertising PDU descriptor, updates link-layer status and an advertised-header byte, builds the advertising PDU via llm_adv_pdu_build, and returns a PDU descriptor initialized by pdu_type_init.",
  "subsystem": "ble",
  "var_renames": {
    "a2": "adv_pdu_desc",
    "v5": "adv_rx_status",
    "v10": "adv_context",
    "v11": "adv_pdu",
    "v12": "adv_alt_pdu",
    "v14": "adv_low_nibble",
    "v16": "adv_seq_counter"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "adv_pdu_desc rx/status or length field"
    },
    {
      "offset": 14,
      "meaning": "adv_pdu_desc RSSI/quality field; 0xFF indicates invalid value"
    },
    {
      "offset": 28,
      "meaning": "adv_pdu_desc alternate/filter flag"
    },
    {
      "offset": 32,
      "meaning": "adv_pdu_desc pointer to advertising context or PDU list"
    },
    {
      "offset": 32,
      "meaning": "a1 pointer to PDU buffer or context"
    },
    {
      "offset": 38,
      "meaning": "a1 uint16 status flags; bit 2 is set here"
    },
    {
      "offset": 20,
      "meaning": "adv_context pointer to alternate advertising PDU"
    },
    {
      "offset": 24,
      "meaning": "adv_context pointer to primary advertising PDU"
    },
    {
      "offset": 22,
      "meaning": "adv_pdu byte holding low nibble flag/state and high-nibble counter"
    }
  ]
}
